'use strict';

// PURE_JS_ONLY_NO_NATIVE: generated bytes + fake machine state. Never construct
// Machine, load guest instructions, or instantiate/compile a WASM module.
const assert = require('node:assert/strict');
const { test } = require('node:test');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const crypto = require('node:crypto');
const { Machine } = require('../tools/toyvm/dos');
const { readReadonlyIso } = require('../tools/toyvm/readonly-iso');
const Cd = require('../lib/cdrom');
const hash = b => crypto.createHash('sha256').update(b).digest('hex');
const SECTOR = 2048;

function both32(b, at, n) { b.writeUInt32LE(n, at); b.writeUInt32BE(n, at + 4); }
function both16(b, at, n) { b.writeUInt16LE(n, at); b.writeUInt16BE(n, at + 2); }
function record(name, lba, size, flags = 0) {
  const id = typeof name === 'number' ? Buffer.from([name]) : Buffer.from(name);
  const b = Buffer.alloc(33 + id.length + (id.length % 2 ? 0 : 1));
  b[0] = b.length; both32(b, 2, lba); both32(b, 10, size);
  b.set([126, 11, 13, 12, 0, 0, 0], 18); // deliberately not the fallback DOS date
  b[25] = flags; both16(b, 28, 1); b[32] = id.length; b.set(id, 33);
  return b;
}
function fixture(extra = []) {
  const b = Buffer.alloc(32 * SECTOR);
  const pvd = b.subarray(16 * SECTOR, 17 * SECTOR);
  pvd.set([1, 67, 68, 48, 48, 49, 1]); pvd.write('TOY_DATA', 40);
  both32(pvd, 80, 32); both16(pvd, 128, SECTOR);
  pvd.set(record(0, 20, SECTOR, 2), 156);
  b.set([255, 67, 68, 48, 48, 49, 1], 17 * SECTOR);
  const payload = Buffer.alloc(5000);
  for (let i = 0; i < payload.length; i++) payload[i] = (i * 7 + 13) & 255;
  const root = [record(0, 20, SECTOR, 2), record(1, 20, SECTOR, 2),
    record('ROOT.TXT;1', 23, 9), record('DATA', 21, SECTOR, 2),
    record('HIDE.BIN;1', 24, 3, 1), ...extra];
  b.set(Buffer.concat(root), 20 * SECTOR);
  b.set(Buffer.concat([record(0, 21, SECTOR, 2), record(1, 20, SECTOR, 2),
    record('NEST', 22, SECTOR, 2)]), 21 * SECTOR);
  b.set(Buffer.concat([record(0, 22, SECTOR, 2), record(1, 21, SECTOR, 2),
    record('BIG.DAT;1', 25, payload.length), record('EMPTY.;1', 28, 0)]), 22 * SECTOR);
  b.write('root-data', 23 * SECTOR); b.set([0, 128, 255], 24 * SECTOR); b.set(payload, 25 * SECTOR);
  return { b, payload };
}
function rawFixture() {
  const { b, payload } = fixture(), raw = Buffer.alloc(36 * 2352, 0xa6);
  for (let s = 0; s < 32; s++) {
    const at = (s + 2) * 2352;
    raw[at] = raw[at + 11] = 0; raw.fill(255, at + 1, at + 11); raw[at + 15] = 1;
    raw.set(b.subarray(s * SECTOR, (s + 1) * SECTOR), at + 16);
  }
  const cue = 'FILE "disc.bin" BINARY\n TRACK 01 MODE1/2352\n INDEX 01 00:00:02\n' +
    ' TRACK 02 AUDIO\n INDEX 00 00:00:34\n INDEX 01 00:00:35\n';
  return { raw, payload, opts: { format: 'mode1/2352', cue, file: 'disc.bin' } };
}
function machine() {
  const m = Object.create(Machine.prototype);
  Object.assign(m, { mem: new Uint8Array(65536), currentDrive: 2, currentDirectory: '',
    driveDirectories: new Map([[0, ''], [1, ''], [2, '']]), floppyVolumes: new Map(), isoVolumes: new Map(),
    mediaChanges: [], files: new Map(), fileNext: 5, filesOpened: [], filesMissed: [], filesCreated: [],
    tempFiles: new Map(), virtualDirectories: new Set(), fileRoot: null, bytesRead: 0, dta: 0x4000,
    directorySearches: new Map(), directorySearchIds: new Map(), directorySearchSerial: 0,
    lin: (r, seg, off) => (r.get(seg) << 4) + off,
    guestRd(at) { return this.mem[at]; }, guestBytes(at, n) { return this.mem.slice(at, at + n); },
    guestWrite(at, b) { this.mem.set(b, at); },
  });
  return m;
}
function call(m, ah, name, args = {}, al = 0) {
  if (name !== undefined) m.mem.set(Buffer.from(name + '\0'), 0x2000);
  const v = { ds: 0x200, dx: 0, ...args };
  assert.equal(m.int21Call(ah, al, { get: k => v[k] || 0, set: (k, n) => v[k] = n,
    setResultCf: on => v.cf = on }), true);
  return v;
}
function fail(v, code) { assert.equal(v.cf, true); assert.equal(v.ax, code); }
function mount(m, b = fixture().b, opts = {}) { return m.mountIso(b, { format: 'iso', ...opts }); }

test('real ISO bytes, nested primary names and detached per-open contents', () => {
  const m = machine(), { b, payload } = fixture(), before = hash(b);
  assert.deepEqual(mount(m, b), { drive: 3, label: 'TOY_DATA', mounted: true, kind: 'iso9660' });
  assert(m.driveAvailable(3)); assert(!m.driveAvailable(4)); assert(m.driveAvailable(2));
  assert.equal(m.keyDrive('d:/data/nest/big.dat'), 3);
  assert.equal(m.fileKey('D:\\DATA/./NEST/../NEST/BIG.DAT'), 'd:/data/nest/big.dat');
  assert.equal(m.parentExists('d:/root.txt'), true);
  assert.equal(m.readWholeFile('d:/ROOT.txt').toString(), 'root-data');
  assert.deepEqual(m.readWholeFile('D:/DATA/NEST/BIG.DAT'), payload);
  assert.equal(m.readWholeFile('C:/ROOT.TXT'), null);
  assert.equal(m.readWholeFile('D:/BIG.DAT'), null);
  assert.equal(m.openFile('D:/DATA'), 0);
  const h = m.openFile('D:/DATA/NEST/BIG.DAT');
  assert.equal(m.files.get(h).readOnly, true);
  m.files.get(h).buf[0] ^= 255;
  assert.deepEqual(m.readWholeFile('D:/DATA/NEST/BIG.DAT'), payload);
  assert.equal(hash(b), before);
});

test('per-drive cwd, D: default drive, rooted/relative paths and C: overlay stay separate', () => {
  const m = machine(); mount(m);
  assert.equal(call(m, 0x39, 'C:/SAVE').cf, false);
  assert.equal(call(m, 0x3b, 'C:/SAVE').cf, false);
  const c = m.createFile('STATE.DAT'); assert(c); m.files.get(c).buf = Buffer.from('C');
  assert.equal(call(m, 0x3b, 'D:/DATA/NEST').cf, false); assert.equal(m.currentDrive, 2);
  assert.equal(m.fileKey('D:BIG.DAT'), 'd:/data/nest/big.dat');
  assert.equal(call(m, 0x0e, undefined, { dx: 3 }).ax & 255, 4);
  assert.equal(m.currentDirectory, 'data/nest');
  assert.equal(m.absolutePath('BIG.DAT'), 'D:\\DATA\\NEST\\BIG.DAT');
  assert.equal(m.fileKey('/ROOT.TXT'), 'd:/root.txt');
  assert.equal(m.fileKey('C:STATE.DAT'), 'save/state.dat');
  assert.equal(call(m, 0x47, undefined, { dx: 4, si: 0x100 }).cf, false);
  assert.equal(Buffer.from(m.mem.subarray(0x2100, 0x210a)).toString(), 'DATA\\NEST\0');
  fail(call(m, 0x3b, 'D:/MISSING'), 3);
  call(m, 0x0e, undefined, { dx: 2 }); assert.equal(m.currentDirectory, 'save');
  for (const name of ['E:/ROOT.TXT', 'D:/DATA:BAD', 'D:/DATA/*', '//D/ROOT.TXT']) assert.equal(m.fileKey(name), null);
});

test('DOS uses primary 8.3 identifiers even when a Joliet descriptor exists', () => {
  const m = machine(), { b } = fixture();
  const svd = Buffer.from(b.subarray(16 * SECTOR, 17 * SECTOR));
  svd[0] = 2; svd.set([0x25, 0x2f, 0x45], 88);
  // The supplementary directory is deliberately different from the primary.
  svd.set(record(0, 29, SECTOR, 2), 156);
  const name = Buffer.from('LONG JOLIET NAME.TXT', 'utf16le');
  for (let i = 0; i < name.length; i += 2) [name[i], name[i + 1]] = [name[i + 1], name[i]];
  const r = record('x'.repeat(name.length), 23, 9); r.set(name, 33);
  b.set(r, 29 * SECTOR); b.set(svd, 17 * SECTOR);
  b.set([255, 67, 68, 48, 48, 49, 1], 18 * SECTOR);
  mount(m, b);
  assert.equal(m.readWholeFile('D:/ROOT.TXT').toString(), 'root-data');
  assert.equal(m.readWholeFile('D:/LONG JOLIET NAME.TXT'), null);
});

test('DOS open/read/seek/EOF/close use actual bytes, including cross-sector reads', () => {
  const m = machine(), { b, payload } = fixture(); mount(m, b);
  const h = call(m, 0x3d, 'D:/DATA/NEST/BIG.DAT').ax;
  assert.equal(call(m, 0x42, undefined, { bx: h, dx: 2040 }).ax, 2040);
  assert.equal(call(m, 0x3f, undefined, { bx: h, cx: 40, ds: 0x300, dx: 0 }).ax, 40);
  assert.deepEqual(Buffer.from(m.mem.subarray(0x3000, 0x3028)), payload.subarray(2040, 2080));
  assert.equal(call(m, 0x42, undefined, { bx: h, cx: 0xffff, dx: 0xfffc }, 2).ax, 4996);
  assert.equal(call(m, 0x3f, undefined, { bx: h, cx: 40, ds: 0x300 }).ax, 4);
  assert.equal(call(m, 0x3f, undefined, { bx: h, cx: 40 }).ax, 0);
  assert.equal(call(m, 0x42, undefined, { bx: h, dx: 6000 }).ax, 6000);
  assert.equal(call(m, 0x3f, undefined, { bx: h, cx: 40 }).ax, 0);
  fail(call(m, 0x42, undefined, { bx: h, cx: 0xffff, dx: 0xffff }), 1);
  fail(call(m, 0x42, undefined, { bx: h }, 3), 1); assert.equal(m.files.get(h).pos, 6000);
  assert.equal(call(m, 0x3e, undefined, { bx: h }).cf, false); assert(!m.files.has(h));
  fail(call(m, 0x3f, undefined, { bx: h, cx: 1 }), 6);
  assert.equal(m.readWholeFile('D:/DATA/NEST/EMPTY').length, 0);
});

test('FindFirst/FindNext return immediate-child names, sizes, flags and unknown timestamps', () => {
  const m = machine(); mount(m);
  assert.equal(call(m, 0x4e, 'D:/DATA/NEST/*.DAT', { cx: 0 }).cf, false);
  const dta = Buffer.from(m.mem.subarray(m.dta, m.dta + 43));
  assert.equal(dta[21], 0x21); assert.equal(dta.readUInt32LE(26), 5000);
  assert.equal(dta.readUInt16LE(22), 0); assert.equal(dta.readUInt16LE(24), 0);
  assert.equal(dta.subarray(30, 38).toString(), 'BIG.DAT\0');
  fail(call(m, 0x4f), 18);
  fail(call(m, 0x4e, 'D:/HIDE.BIN'), 2);
  assert.equal(call(m, 0x4e, 'D:/HIDE.BIN', { cx: 2 }).cf, false); assert.equal(m.mem[m.dta + 21], 0x23);
  assert.equal(call(m, 0x4e, 'D:/DATA', { cx: 0x10 }).cf, false); assert.equal(m.mem[m.dta + 21], 0x11);
  fail(call(m, 0x4e, 'D:/MISSING/*.*'), 3);
  assert.equal(call(m, 0x43, 'D:/ROOT.TXT').cx, 0x21);
  assert.equal(call(m, 0x43, 'D:/DATA').cx, 0x11);
  assert.equal(call(m, 0x43, 'D:/').cx, 0x11);
  const space = call(m, 0x36, undefined, { dx: 4 });
  assert.equal(space.cx, 2048); assert.equal(space.dx * space.ax, 32); assert.equal(space.bx, 0);
});

test('all implemented mutation services reject the ISO and leave source and C: intact', () => {
  const m = machine(), { b } = fixture(), before = hash(b); mount(m, b);
  m.tempFiles.set('keep', { data: Buffer.from('C'), len: 1 });
  for (const al of [1, 2, 3]) fail(call(m, 0x3d, 'D:/ROOT.TXT', {}, al), 5);
  for (const ah of [0x3c, 0x41, 0x39]) fail(call(m, ah, 'D:/ROOT.TXT'), 5);
  fail(call(m, 0x5a, 'D:/'), 5);
  assert.equal(Buffer.from(m.mem.subarray(0x2000, 0x2004)).toString(), 'D:/\0');
  fail(call(m, 0x43, 'D:/ROOT.TXT', { cx: 0 }, 1), 5);
  m.mem.set(Buffer.from('D:/NEW.TXT\0'), 0x3000);
  fail(call(m, 0x56, 'D:/ROOT.TXT', { es: 0x300, di: 0 }), 5);
  const h = call(m, 0x3d, 'D:/ROOT.TXT').ax;
  fail(call(m, 0x40, undefined, { bx: h, cx: 1 }), 5);
  fail(call(m, 0x40, undefined, { bx: h, cx: 0 }), 5);
  fail(call(m, 0x57, undefined, { bx: h }, 1), 5);
  assert.throws(() => m.writeFile(m.files.get(h), 0, 1), /read-only/);
  assert.equal(hash(b), before); assert.equal(m.tempFiles.size, 1);
  assert.equal(m.readWholeFile('C:/keep').toString(), 'C');
});

test('invalid and colliding mounts fail atomically; A:/B: remain FAT namespaces', () => {
  const m = machine();
  // Exercise existing FAT mounting itself, rather than replacing its parser.
  const fat = Buffer.alloc(512 * 10); fat.writeUInt16LE(512, 11); fat[13] = fat[14] = fat[16] = 1;
  fat.writeUInt16LE(16, 17); fat.writeUInt16LE(10, 19); fat.writeUInt16LE(1, 22);
  fat[510] = 0x55; fat[511] = 0xaa; fat.set([0xf0, 0xff, 0xff, 0xff, 0x0f], 512);
  fat.write('SAME    TXT', 1024); fat[1035] = 0x20; fat.writeUInt16LE(2, 1050); fat.writeUInt32LE(3, 1052);
  fat.write('FAT', 1536);
  m.changeDisk('A', fat); m.changeDisk('B', fat);
  assert.equal(m.readWholeFile('A:/SAME.TXT').toString(), 'FAT');
  assert.equal(m.readWholeFile('B:/SAME.TXT').toString(), 'FAT');
  for (const drive of ['A', 'B', 'C', 'AA', '../D', 3]) assert.throws(() => mount(m, fixture().b, { drive }), /drive/);
  assert.throws(() => mount(m, Buffer.alloc(2048)), /small/);
  assert.equal(m.isoVolumes.size, 0); assert.equal(m.currentDrive, 2);
  mount(m); const volume = m.isoVolumes.get(3), changes = m.mediaChanges.length;
  assert.throws(() => mount(m), /already mounted/); assert.equal(m.isoVolumes.get(3), volume);
  assert.equal(m.mediaChanges.length, changes);
  assert.equal(m.readWholeFile('A:/SAME.TXT').toString(), 'FAT');
  assert.throws(() => m.changeDisk('D', fat), /floppy/);
  mount(m, fixture().b, { drive: 'Z:' }); assert.equal(call(m, 0x0e, undefined, { dx: 25 }).ax & 255, 26);
  assert.equal(m.absolutePath('/ROOT.TXT'), 'Z:\\ROOT.TXT');
});

test('strict mount bounds and unsupported ISO records/names never become DOS files', () => {
  const checks = [
    [() => fixture([record('ROOT.TXT;2', 24, 1)]).b, /both mount|collision/],
    [() => fixture([record('TOOLONGNAME.TXT;1', 24, 1)]).b, /8.3/],
    [() => fixture([record('A[B.TXT;1', 24, 1)]).b, /8.3/],
    [() => fixture([record('NUL.;1', 24, 1)]).b, /device/],
    [() => fixture([record('OUT.BIN;1', 32, 1)]).b, /bounds/],
    [() => fixture([record('MULTI.BIN;1', 24, 1, 0x80)]).b, /multi-extent/],
    [() => { const b = fixture().b; both32(b, 16 * SECTOR + 80, 33); return b; }, /bounds/],
    [() => { const b = fixture().b; both32(b, 16 * SECTOR + 80, 19); return b; }, /bounds/],
    [() => { const b = fixture().b; b[16 * SECTOR + 84] ^= 1; return b; }, /disagrees/],
    [() => { const b = fixture().b; both32(b, 16 * SECTOR + 158, 33); return b; }, /root directory extent/],
  ];
  for (const [build, error] of checks) {
    const m = machine(); assert.throws(() => mount(m, build()), error);
    assert.equal(m.isoVolumes.size, 0); assert.equal(m.mediaChanges.length, 0);
  }
  const b = fixture().b;
  assert.throws(() => readReadonlyIso(b), /explicit format/);
  assert.throws(() => readReadonlyIso(b, { format: 'bin' }), /explicit format/);
  assert.throws(() => readReadonlyIso(b.subarray(0, b.length - 1), { format: 'iso' }), /multiple/);
  assert.throws(() => readReadonlyIso({ size: NaN, readRange() {} }, { format: 'iso' }), /size/);
  assert.throws(() => readReadonlyIso({ size: b.length, readRange: () => b.subarray(0, 2) }, { format: 'iso' }), /short/);
  assert.throws(() => readReadonlyIso({ size: b.length, readRange: async () => b }, { format: 'iso' }), /asynchronous/);
});

test('raw MODE1/2352 data map honors CUE offset/end and retains audio/CUE untouched', async () => {
  const { raw, payload, opts } = rawFixture(), before = hash(raw), reads = [];
  const m = machine(); m.mountIso({ size: raw.length, readRange(o, n) { reads.push([o, n]); return raw.subarray(o, o + n); } }, opts);
  assert.deepEqual(m.readWholeFile('D:/DATA/NEST/BIG.DAT'), payload);
  const shared = Cd.mode1Provider({ size: raw.length, readRange: (o, n) => raw.subarray(o, o + n) },
    { type: 'MODE1/2352', byteOffset: 2 * 2352, sectors: 32 });
  assert.deepEqual(m.readWholeFile('D:/DATA/NEST/BIG.DAT'), Buffer.from(await shared.readRange(25 * 2048, 5000)));
  const media = m.isoVolumes.get(3).media;
  assert.equal(media.cueText, opts.cue); assert.equal(media.cue.tracks.length, 2);
  assert.equal(media.cue.tracks[1].isAudio, true); assert.equal(media.range.startSector, 2);
  assert.equal(media.range.endSector, 34);
  assert(reads.every(([o, n]) => o >= 2 * 2352 && o + n <= 34 * 2352));
  assert.equal(hash(raw), before);
  assert.throws(() => readReadonlyIso(raw, { format: 'iso' }), /multiple|CD001/);
  assert.throws(() => readReadonlyIso(raw, { format: 'mode1/2352' }), /CUE/);
  assert.throws(() => readReadonlyIso(raw, { ...opts, file: 'other.bin' }), /supplied FILE/);
  assert.throws(() => readReadonlyIso(raw.subarray(0, raw.length - 1), opts), /multiple/);
  const corrupt = Buffer.from(raw); corrupt[(16 + 2) * 2352 + 15] = 2;
  assert.throws(() => readReadonlyIso(corrupt, opts), /sector header/);
  const overrun = Buffer.from(raw); both32(overrun, (16 + 2) * 2352 + 16 + 80, 35);
  assert.throws(() => readReadonlyIso(overrun, opts), /bounds/);
});

test('filesystem provider is lazy, bounded and read-only; failed later reads do not open handles', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'toyvm-iso-pure-'));
  const file = path.join(dir, 'tiny.iso'), { b, payload } = fixture();
  fs.writeFileSync(file, b); const fd = fs.openSync(file, 'r'), reads = [];
  let broken = false;
  try {
    const source = { size: b.length, readRange(offset, length) {
      reads.push([offset, length]); if (broken) return new Uint8Array();
      const out = Buffer.alloc(length), got = fs.readSync(fd, out, 0, length, offset); return out.subarray(0, got);
    } };
    const m = machine(); m.mountIso(source, { format: 'iso' });
    assert(reads.every(([o]) => o < 23 * SECTOR), 'mount reads descriptors and directory tree only');
    assert.deepEqual(m.readWholeFile('D:/DATA/NEST/BIG.DAT'), payload);
    const h = m.openFile('D:/ROOT.TXT'), next = m.fileNext; broken = true;
    assert.equal(m.openFile('D:/ROOT.TXT'), 0); assert.equal(m.fileNext, next);
    assert.equal(m.files.size, 1); assert.equal(Buffer.from(m.files.get(h).buf).toString(), 'root-data');
    assert.equal(m.readWholeFile('D:/ROOT.TXT'), null);
    assert.equal(hash(fs.readFileSync(file)), hash(b));
  } finally { fs.closeSync(fd); fs.rmSync(dir, { recursive: true, force: true }); }
});
